-- Questionários de pré-onboarding (Vendas e Locação), preenchidos pelo consultor com o cliente.
-- Perguntas ficam em questionarios_template.estrutura (JSON). Cada pergunta tem `ativo` (omitido = ativa)
-- e `nota_revisao` (por que foi inativada/alterada). A edição é restrita a admin na interface (a política do banco continua admin e diretor).

ALTER TABLE public.questionarios_template ADD COLUMN IF NOT EXISTS segmento text;

-- O template genérico de exemplo deixa de ser o ativo (os questionários já criados continuam apontando para ele).
UPDATE public.questionarios_template
   SET ativo = false
 WHERE segmento IS NULL AND nome = 'Pré-Onboarding CUPOLA';

INSERT INTO public.questionarios_template (nome, versao, ativo, segmento, estrutura)
SELECT 'Pré-Onboarding Consultoria — Vendas (2026)', 1, true, 'vendas', $tpl${"secoes": [{"id": "qualificacao", "titulo": "1. Qualificação", "perguntas": [{"id": "v_1_1", "codigo": "1.1", "tipo": "texto_curto", "label": "Nome da imobiliária", "obrigatorio": false}, {"id": "v_1_2", "codigo": "1.2", "tipo": "texto_curto", "label": "Nome e cargo do executivo responsável pelas respostas", "obrigatorio": false}, {"id": "v_1_3", "codigo": "1.3", "tipo": "texto_longo", "label": "Tempo de atuação da imobiliária", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: contar a história na fala contribui mais do que citar a quantidade de tempo (coletar na entrevista)."}, {"id": "v_1_4", "codigo": "1.4", "tipo": "numero", "label": "Número de sócios", "obrigatorio": false}, {"id": "v_1_5", "codigo": "1.5", "tipo": "texto_longo", "label": "Número de sedes", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. As cidades de atuação (1.6) já dão a dimensão territorial."}, {"id": "v_1_6", "codigo": "1.6", "tipo": "texto_curto", "label": "Cidades de atuação", "obrigatorio": false}, {"id": "v_1_7", "codigo": "1.7", "tipo": "texto_longo", "label": "Participa de alguma rede imobiliária?", "obrigatorio": false}, {"id": "v_1_8", "codigo": "1.8", "tipo": "texto_longo", "label": "Quais ramos, além de vendas, a sua imobiliária atua? (Por exemplo: Locação / Administração de condomínios / Consórcios / Locação de temporada)", "obrigatorio": false}, {"id": "v_1_9", "codigo": "1.9", "tipo": "texto_longo", "label": "Qual a contribuição individual desses ramos no resultado geral da empresa?", "obrigatorio": false}, {"id": "v_1_10", "codigo": "1.10", "tipo": "texto_longo", "label": "Qual o ticket médio dos imóveis à venda ANUNCIADOS atualmente na imobiliária?", "obrigatorio": false, "dica": "Quais os perfis de imóveis que estão anunciados no \"estoque\" da imobiliária atualmente?"}, {"id": "v_1_11", "codigo": "1.11", "tipo": "numero", "label": "Número de imóveis de vendas em divulgação atualmente", "obrigatorio": false}, {"id": "v_1_12", "codigo": "1.12", "tipo": "numero", "label": "Número de imóveis vendidos nos últimos 12 meses", "obrigatorio": false}, {"id": "v_1_13", "codigo": "1.13", "tipo": "texto_curto", "label": "Valor geral de vendas (VGV) dos últimos 12 meses", "obrigatorio": false}, {"id": "v_1_14", "codigo": "1.14", "tipo": "texto_curto", "label": "Valor geral de comissões (VGC) dos últimos 12 meses", "obrigatorio": false}, {"id": "v_1_15", "codigo": "1.15", "tipo": "numero", "label": "Número de corretores dedicados às vendas", "obrigatorio": false}, {"id": "v_1_16", "codigo": "1.16", "tipo": "texto_longo", "label": "Qual a participação (%) de cada produto (Novos e Lançamentos x Usados) nas vendas dos últimos 12 meses?", "obrigatorio": false}, {"id": "v_1_17", "codigo": "1.17", "tipo": "sim_nao", "label": "Tem correspondente bancário parceiro ou dentro da imobiliária?", "obrigatorio": false, "nota_revisao": "Riscada pela Vivian, mas mantida: a existência de correspondente bancário afeta diretamente a conversão e é base da 1.18. Reavalie se preferir."}, {"id": "v_1_18", "codigo": "1.18", "tipo": "texto_longo", "label": "Quais as alternativas oferecidas para um cliente que tem o financiamento imobiliário reprovado?", "obrigatorio": false, "dica": "Como a imobiliária conduz o cliente nos cenários em que há financiamento imobiliário reprovado?"}, {"id": "v_1_19", "codigo": "1.19", "tipo": "texto_longo", "label": "A sua imobiliária é especialista em algum tipo de produto, ticket ou nicho? Se sim, qual?", "obrigatorio": false}, {"id": "v_1_20", "codigo": "1.20", "tipo": "texto_longo", "label": "Qual o perfil médio dos seus clientes (renda, composição familiar, estudantes etc.)?", "obrigatorio": false}, {"id": "v_1_21", "codigo": "1.21", "tipo": "texto_longo", "label": "Quais são os três principais diferenciais da sua imobiliária?", "obrigatorio": false}, {"id": "v_1_22", "codigo": "1.22", "tipo": "texto_longo", "label": "Como você gostaria que a sua imobiliária fosse reconhecida?", "obrigatorio": false}, {"id": "v_1_23", "codigo": "1.23", "tipo": "texto_longo", "label": "Possui missão, visão e valores? Se sim, quais são?", "obrigatorio": false}, {"id": "v_1_24", "codigo": "1.24", "tipo": "texto_longo", "label": "Quais são as três principais dores da imobiliária quanto à operação de vendas?", "obrigatorio": false}]}, {"id": "mercado", "titulo": "2. Mercado", "perguntas": [{"id": "v_2_1", "codigo": "2.1", "tipo": "texto_longo", "label": "Qual o tamanho do mercado em que atua (número de imóveis à venda em divulgação)?", "obrigatorio": false}, {"id": "v_2_2", "codigo": "2.2", "tipo": "texto_longo", "label": "Qual a sua participação em vendas (%) dentro do mercado em que atua?", "obrigatorio": false}, {"id": "v_2_3", "codigo": "2.3", "tipo": "texto_longo", "label": "Quem são os seus principais concorrentes em vendas?", "obrigatorio": false}, {"id": "v_2_4", "codigo": "2.4", "tipo": "texto_longo", "label": "Como você avalia os seus concorrentes em vendas? O que eles fazem de diferente que você acha que seria positivo aplicar na sua imobiliária?", "obrigatorio": false}, {"id": "v_2_5", "codigo": "2.5", "tipo": "sim_nao", "label": "A exclusividade da venda é uma prática comum no seu mercado de atuação?", "obrigatorio": false}, {"id": "v_2_6", "codigo": "2.6", "tipo": "texto_longo", "label": "Quanto os seus concorrentes pagam em média de comissão para captação e intermediação da venda?", "obrigatorio": false}, {"id": "v_2_7", "codigo": "2.7", "tipo": "texto_longo", "label": "Quais os três principais desafios da sua imobiliária em relação ao seu mercado de atuação (seus concorrentes, práticas do mercado e outros players que se relacionam com a imobiliária) quando falamos da operação de vendas?", "obrigatorio": false}]}, {"id": "gestao-de-pessoas", "titulo": "3. Gestão de Pessoas", "perguntas": [{"id": "v_3_1", "codigo": "3.1", "tipo": "texto_longo", "label": "Quantos colaboradores são dedicados à operação de vendas? Descreva quantos são CLT e quantos são PJ.", "obrigatorio": false}, {"id": "v_3_2", "codigo": "3.2", "tipo": "texto_longo", "label": "Em quais departamentos estes colaboradores se dividem?", "obrigatorio": false}, {"id": "v_3_3", "codigo": "3.3", "tipo": "texto_longo", "label": "Em quais outras áreas da imobiliária os colaboradores de vendas atuam? (por exemplo, locação, condomínios, administração)", "obrigatorio": false, "dica": "Os colaboradores citados são totalmente dedicados à operação de vendas? Há algum que se divide com outra frente? Se sim, qual?"}, {"id": "v_3_4", "codigo": "3.4", "tipo": "texto_longo", "label": "A imobiliária dispõe de uma pessoa dedicada à gestão de pessoas ou recursos humanos? Se sim, qual o nome e cargo dela?", "obrigatorio": false, "dica": "Quais os principais focos deste profissional na operação?"}, {"id": "v_3_5", "codigo": "3.5", "tipo": "texto_longo", "label": "Quem participa da seleção de novos corretores?", "obrigatorio": false}, {"id": "v_3_6", "codigo": "3.6", "tipo": "texto_longo", "label": "A imobiliária tem organograma da operação de vendas?", "obrigatorio": false}, {"id": "v_3_7", "codigo": "3.7", "tipo": "texto_longo", "label": "A imobiliária tem descritivos de cargos com perfil desejado para as funções CLT e não CLT na frente de vendas?", "obrigatorio": false}, {"id": "v_3_8", "codigo": "3.8", "tipo": "texto_longo", "label": "Qual o principal canal de atração de novos corretores? (por exemplo, LinkedIn, indicação, Instagram, eventos)", "obrigatorio": false}, {"id": "v_3_9", "codigo": "3.9", "tipo": "texto_longo", "label": "A imobiliária realiza, regularmente (trimestral, semestral, anual), avaliação de desempenho das equipes de vendas? Como ela é feita?", "obrigatorio": false}, {"id": "v_3_10", "codigo": "3.10", "tipo": "texto_longo", "label": "Quais os três principais desafios em termos de gestão de pessoas/equipe relacionada ao segmento de vendas?", "obrigatorio": false}]}, {"id": "marketing", "titulo": "4. Mídia e Marketing", "perguntas": [{"id": "v_4_1", "codigo": "4.1", "tipo": "texto_longo", "label": "Como é a estrutura de marketing da imobiliária? Agência externa, time interno? Se tiver, qual o tamanho do time interno?", "obrigatorio": false}, {"id": "v_4_2", "codigo": "4.2", "tipo": "sim_nao", "label": "O nome da sua marca é registrado?", "obrigatorio": false}, {"id": "v_4_3", "codigo": "4.3", "tipo": "texto_longo", "label": "Quem é o responsável pela estratégia/planejamento de marketing?", "obrigatorio": false}, {"id": "v_4_4", "codigo": "4.4", "tipo": "texto_longo", "label": "Qual a sua estratégia de posicionamento hoje? (Padrão do imóvel, região de atuação, etc.)", "obrigatorio": false}, {"id": "v_4_5", "codigo": "4.5", "tipo": "texto_longo", "label": "Você possui uma estratégia de comunicação interna?", "obrigatorio": false}, {"id": "v_4_6", "codigo": "4.6", "tipo": "texto_longo", "label": "Quanto você investe mensalmente considerando mídia online (Meta Ads, Google Ads, LinkedIn Ads, etc.)?", "obrigatorio": false}, {"id": "v_4_7", "codigo": "4.7", "tipo": "texto_longo", "label": "Quais são os objetivos das campanhas em Facebook e Instagram: alcance, tráfego no site e/ou geração de cadastros?", "obrigatorio": false}, {"id": "v_4_8", "codigo": "4.8", "tipo": "texto_longo", "label": "As campanhas de mídia online são separadas por funil? Existem campanhas para imóveis específicos?", "obrigatorio": false}, {"id": "v_4_9", "codigo": "4.9", "tipo": "texto_longo", "label": "Os criativos das campanhas são atualizados com que frequência?", "obrigatorio": false}, {"id": "v_4_10", "codigo": "4.10", "tipo": "texto_longo", "label": "O que é considerado conversão? (lead, visita, contato WhatsApp)", "obrigatorio": false}, {"id": "v_4_11", "codigo": "4.11", "tipo": "texto_longo", "label": "Qual a origem dos leads que mais geram venda (Meta Ads, Google Ads, Site Orgânico, WhatsApp, etc.)?", "obrigatorio": false}, {"id": "v_4_12", "codigo": "4.12", "tipo": "texto_longo", "label": "Em quais portais imobiliários está presente?", "obrigatorio": false}, {"id": "v_4_13", "codigo": "4.13", "tipo": "texto_longo", "label": "Qual o investimento mensal em portais? Descreva o investimento em cada portal que você anuncia.", "obrigatorio": false}, {"id": "v_4_14", "codigo": "4.14", "tipo": "texto_longo", "label": "Os portais imobiliários estão integrados ao seu sistema de gestão de imóveis para envio dos anúncios de forma automatizada?", "obrigatorio": false}, {"id": "v_4_15", "codigo": "4.15", "tipo": "texto_longo", "label": "As campanhas de mídia online e os portais imobiliários estão integrados ao seu sistema de gestão de leads para recebimento automático dentro do CRM?", "obrigatorio": false}, {"id": "v_4_16", "codigo": "4.16", "tipo": "texto_longo", "label": "Quanto você investe mensalmente em ações e mídia offline (outdoor, flyers, folders, rádio, revista, jornal, televisão, parcerias de experiência, etc.)?", "obrigatorio": false}, {"id": "v_4_17", "codigo": "4.17", "tipo": "texto_longo", "label": "Quantos leads (contatos novos) foram gerados nos últimos 12 meses?", "obrigatorio": false}, {"id": "v_4_18", "codigo": "4.18", "tipo": "texto_longo", "label": "Responde regularmente o Google Meu Negócio e o Reclame Aqui?", "obrigatorio": false}, {"id": "v_4_19", "codigo": "4.19", "tipo": "texto_longo", "label": "Realiza disparos de e-mails regularmente para a base de leads? Se sim, qual a frequência e qual software usa?", "obrigatorio": false}, {"id": "v_4_20", "codigo": "4.20", "tipo": "texto_curto", "label": "Qual a plataforma do site (WordPress, Loft, Universal, Rocket, etc.)?", "obrigatorio": false}, {"id": "v_4_21", "codigo": "4.21", "tipo": "texto_longo", "label": "Como você avalia a experiência do seu site hoje (rápido, fácil de encontrar os imóveis, possui informações suficientes, bonito)?", "obrigatorio": false}, {"id": "v_4_22", "codigo": "4.22", "tipo": "texto_longo", "label": "Você está satisfeito com o tráfego orgânico do seu site? Quantas palavras-chave possui nas 10 primeiras posições?", "obrigatorio": false}, {"id": "v_4_23", "codigo": "4.23", "tipo": "texto_longo", "label": "Existe estratégia de SEO definida hoje?", "obrigatorio": false}, {"id": "v_4_24", "codigo": "4.24", "tipo": "texto_longo", "label": "Possui blog ativo? Se sim, é atualizado com qual frequência?", "obrigatorio": false}, {"id": "v_4_25", "codigo": "4.25", "tipo": "texto_longo", "label": "A imobiliária incentiva que os corretores façam mídia por conta própria em portais e redes sociais?", "obrigatorio": false}, {"id": "v_4_26", "codigo": "4.26", "tipo": "texto_longo", "label": "O que já funciona bem no marketing da sua imobiliária?", "obrigatorio": false}, {"id": "v_4_27", "codigo": "4.27", "tipo": "texto_longo", "label": "Quais são os três principais desafios relacionados ao marketing na sua imobiliária?", "obrigatorio": false}]}, {"id": "captacao", "titulo": "5. Captação", "perguntas": [{"id": "v_5_1", "codigo": "5.1", "tipo": "texto_longo", "label": "Usa algum CRM e/ou sistema de gestão de imóveis? Se sim, qual?", "obrigatorio": false}, {"id": "v_5_2", "codigo": "5.2", "tipo": "numero", "label": "Qual a média de imóveis para venda captados POR MÊS nos últimos 12 meses?", "obrigatorio": false}, {"id": "v_5_3", "codigo": "5.3", "tipo": "texto_longo", "label": "Qual a meta mensal de novas captações para vendas?", "obrigatorio": false, "dica": "Esta meta considera apenas as captações ativas ou as passivas também? Atualmente, em média, o time entrega o resultado proposto?"}, {"id": "v_5_4", "codigo": "5.4", "tipo": "texto_longo", "label": "Qual o percentual de comissão pago ao corretor captador sobre o total da comissão?", "obrigatorio": false}, {"id": "v_5_5", "codigo": "5.5", "tipo": "texto_longo", "label": "Existe uma área ou pessoa 100% dedicada à captação para VENDAS? Se sim, quantas pessoas atuam nesta área?", "obrigatorio": false}, {"id": "v_5_6", "codigo": "5.6", "tipo": "texto_longo", "label": "Se não, quem atende as captações receptivas, quando o proprietário procura a imobiliária para deixar um imóvel para vender?", "obrigatorio": false}, {"id": "v_5_7", "codigo": "5.7", "tipo": "texto_longo", "label": "Se a área de captação existe, existe um gestor? Quem é e qual o cargo?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada (gestão da captação é melhor levantada na entrevista; a 5.5 já indica se há área dedicada)."}, {"id": "v_5_8", "codigo": "5.8", "tipo": "texto_longo", "label": "Quem faz e como é feita a avaliação dos imóveis captados?", "obrigatorio": false}, {"id": "v_5_9", "codigo": "5.9", "tipo": "texto_longo", "label": "A imobiliária utiliza alguma ferramenta/tecnologia para apoiar a avaliação dos imóveis?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. A 5.8 já cobre como a avaliação é feita, incluindo ferramentas."}, {"id": "v_5_10", "codigo": "5.10", "tipo": "texto_longo", "label": "Todos os colaboradores da imobiliária podem ou são remunerados por captações? Se sim, qual é a remuneração oferecida a esses colaboradores?", "obrigatorio": false}, {"id": "v_5_11", "codigo": "5.11", "tipo": "texto_curto", "label": "Da atual carteira em divulgação para VENDA, qual é o percentual de imóveis COM exclusividade?", "obrigatorio": false, "nota_revisao": "Riscada pela Vivian, mas mantida: o percentual de exclusividade é indicador-chave de captação e não é coberto por outra pergunta (a 2.5 trata do mercado, não da carteira)."}, {"id": "v_5_12", "codigo": "5.12", "tipo": "texto_longo", "label": "Existe um direcionamento da imobiliária para captar imóveis dentro de um perfil desejado para o estoque? Se sim, qual é o perfil desejado?", "obrigatorio": false}, {"id": "v_5_13", "codigo": "5.13", "tipo": "texto_longo", "label": "Existe diferença de comissionamento para imóveis captados fora desse perfil de interesse? Se sim, qual o percentual nesses casos?", "obrigatorio": false}, {"id": "v_5_14", "codigo": "5.14", "tipo": "texto_longo", "label": "Há algum programa de parceria com corretores autônomos, zeladores, porteiros etc.? Se existe, explique como funciona, quem faz a gestão e o que é oferecido em troca de indicações.", "obrigatorio": false}, {"id": "v_5_15", "codigo": "5.15", "tipo": "texto_longo", "label": "Quem é responsável pela colocação da placa da imobiliária?", "obrigatorio": false}, {"id": "v_5_16", "codigo": "5.16", "tipo": "texto_longo", "label": "Quem é responsável pelas fotos do imóvel?", "obrigatorio": false, "dica": "Todos os imóveis captados têm novas fotos feitas pelo responsável? Há um padrão nas fotografias?"}, {"id": "v_5_17", "codigo": "5.17", "tipo": "texto_longo", "label": "Quem é responsável por redigir o descritivo do imóvel para o site da imobiliária?", "obrigatorio": false, "dica": "Este(s) profissional(is) foram orientados a utilizar IA na construção do descritivo?"}, {"id": "v_5_18", "codigo": "5.18", "tipo": "texto_longo", "label": "Quem é responsável por cadastrar o imóvel no sistema de gestão de imóveis da imobiliária?", "obrigatorio": false}, {"id": "v_5_19", "codigo": "5.19", "tipo": "texto_longo", "label": "Existe algum padrão ou melhores práticas para a redação do descritivo de imóveis?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. A 5.17 já cobre o descritivo."}, {"id": "v_5_20", "codigo": "5.20", "tipo": "texto_longo", "label": "Existe algum padrão ou melhores práticas para a fotografia de imóveis?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. A 5.16 já cobre o padrão das fotos."}, {"id": "v_5_21", "codigo": "5.21", "tipo": "texto_longo", "label": "Existe alguma ferramenta de inteligência artificial aplicada aos descritivos dos imóveis?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. A dica da 5.17 já pergunta sobre uso de IA."}, {"id": "v_5_22", "codigo": "5.22", "tipo": "texto_longo", "label": "O captador tem algum tipo de prioridade ou exclusividade sobre o atendimento ao lead candidato a comprador?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada."}, {"id": "v_5_23", "codigo": "5.23", "tipo": "texto_longo", "label": "Quem comunica o proprietário sobre propostas ao imóvel: captador, corretor ou ambos?", "obrigatorio": false}, {"id": "v_5_24", "codigo": "5.24", "tipo": "texto_longo", "label": "Como a comunicação de propostas é formalizada ao proprietário (ex.: ligação, e-mail, WhatsApp)?", "obrigatorio": false}, {"id": "v_5_25", "codigo": "5.25", "tipo": "texto_longo", "label": "O proprietário é informado quando o imóvel já está disponível para visualização no site da imobiliária?", "obrigatorio": false}, {"id": "v_5_26", "codigo": "5.26", "tipo": "texto_longo", "label": "Existe uma rotina de apresentação à equipe dos imóveis captados? Se sim, como, com qual frequência e quem conduz?", "obrigatorio": false}, {"id": "v_5_27", "codigo": "5.27", "tipo": "texto_longo", "label": "Utiliza algum software de enriquecimento de dados para ter acesso às informações de proprietários de imóveis (ex.: Procob, Assertiva, Fenyx etc.)?", "obrigatorio": false}, {"id": "v_5_28", "codigo": "5.28", "tipo": "texto_longo", "label": "Qual a documentação exigida para finalizar a captação e anunciar o imóvel na sua imobiliária?", "obrigatorio": false}, {"id": "v_5_29", "codigo": "5.29", "tipo": "texto_longo", "label": "Quais os seus três principais desafios em termos de captação de imóveis para venda?", "obrigatorio": false}, {"id": "v_5_30", "codigo": "5.30", "tipo": "texto_longo", "label": "Com qual frequência ocorre a atualização dos imóveis captados?", "obrigatorio": false}, {"id": "v_5_31", "codigo": "5.31", "tipo": "texto_longo", "label": "Quais as estratégias de captação adotadas pela equipe de vendas?", "obrigatorio": false}]}, {"id": "atendimento", "titulo": "6. Atendimento", "perguntas": [{"id": "v_6_1", "codigo": "6.1", "tipo": "texto_longo", "label": "Quem faz o primeiro atendimento de clientes interessados em comprar? Tem uma equipe/pessoa dedicada a essa tarefa ou são os próprios corretores?", "obrigatorio": false, "dica": "O primeiro atendimento é executado por corretores, por colaborador dedicado ou por IA?"}, {"id": "v_6_2", "codigo": "6.2", "tipo": "texto_longo", "label": "De que forma monitora o tempo de resposta do 1º atendimento?", "obrigatorio": false, "nota_revisao": "Revisão Vivian: pergunta original (WhatsApp exclusivo para vendas) riscada e substituída por esta, sugerida por ela."}, {"id": "v_6_3", "codigo": "6.3", "tipo": "texto_longo", "label": "Existe alguma ferramenta omnichannel para receber os leads ou o atendimento é feito diretamente pelo telefone dos corretores?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada."}, {"id": "v_6_4", "codigo": "6.4", "tipo": "texto_longo", "label": "Utiliza alguma ferramenta de inteligência artificial para realizar o primeiro atendimento de novos leads?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. O uso de IA entrou como dica da 6.1."}, {"id": "v_6_5", "codigo": "6.5", "tipo": "texto_curto", "label": "Qual o CRM utilizado para registro dos leads gerados?", "obrigatorio": false}, {"id": "v_6_6", "codigo": "6.6", "tipo": "texto_longo", "label": "Qual o objetivo desse primeiro atendimento?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada."}, {"id": "v_6_7", "codigo": "6.7", "tipo": "texto_longo", "label": "Existe algum script de primeiro atendimento para apoiar a pessoa responsável?", "obrigatorio": false, "dica": "Há script e/ou treinamento frequente?"}, {"id": "v_6_8", "codigo": "6.8", "tipo": "texto_longo", "label": "No primeiro atendimento, utilizam alguma metodologia de qualificação de leads para priorização de atendimento?", "obrigatorio": false}, {"id": "v_6_9", "codigo": "6.9", "tipo": "texto_longo", "label": "Todos os canais de geração de leads (portais, site, WhatsApp etc.) estão integrados ao CRM? Há leads que chegam por outro canal? Qual?", "obrigatorio": false, "nota_revisao": "Revisão Vivian: as perguntas 'como chegam os contatos de portais' e 'do site' foram riscadas e substituídas por esta, sugerida por ela."}, {"id": "v_6_10", "codigo": "6.10", "tipo": "texto_longo", "label": "Como chegam os contatos do site da imobiliária (e-mail, dentro do CRM etc.)?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Coberta pela 6.9."}, {"id": "v_6_11", "codigo": "6.11", "tipo": "texto_longo", "label": "Como funciona a distribuição das leads após o primeiro atendimento?", "obrigatorio": false}, {"id": "v_6_12", "codigo": "6.12", "tipo": "texto_longo", "label": "Existe algum tipo de priorização de atendimento a contatos do site, portais, chat, WhatsApp etc.?", "obrigatorio": false}, {"id": "v_6_13", "codigo": "6.13", "tipo": "texto_longo", "label": "Existe um prazo máximo combinado para que todas as leads tenham um retorno da imobiliária? Como você controla se o prazo está sendo cumprido?", "obrigatorio": false, "dica": "Os corretores têm até quanto tempo para fornecer a 1ª resposta ao lead? Caso não cumpra, há alguma penalidade?"}, {"id": "v_6_14", "codigo": "6.14", "tipo": "texto_longo", "label": "E caso o prazo acima não seja cumprido, qual a estratégia adotada para que o lead seja atendido?", "obrigatorio": false}, {"id": "v_6_15", "codigo": "6.15", "tipo": "texto_longo", "label": "Em que momento a visita é ofertada? O agendamento das visitas é registrado no CRM?", "obrigatorio": false, "dica": "A visita é realizada após uma qualificação? Se sim, quais perguntas o corretor geralmente faz?"}, {"id": "v_6_16", "codigo": "6.16", "tipo": "texto_longo", "label": "Existe algum tipo de controle sobre se e como foi feito o atendimento de todos os clientes que procuraram a imobiliária?", "obrigatorio": false}, {"id": "v_6_17", "codigo": "6.17", "tipo": "texto_longo", "label": "Todas as leads recebidas são cadastradas em CRM, outro sistema ou planilha, ou apenas as que respondem?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Coberta pela 6.9 (integração dos canais ao CRM)."}, {"id": "v_6_18", "codigo": "6.18", "tipo": "numero", "label": "Quantas tentativas de contato são feitas com o lead até o seu descarte?", "obrigatorio": false}, {"id": "v_6_19", "codigo": "6.19", "tipo": "texto_longo", "label": "Qual trabalho é realizado com as leads descartadas ou não aproveitadas?", "obrigatorio": false, "nota_revisao": "Revisão Vivian: pediu para separar a pergunta original em duas (6.19 e 6.20)."}, {"id": "v_6_20", "codigo": "6.20", "tipo": "texto_longo", "label": "Como é feito o trabalho de resgate dessas leads?", "obrigatorio": false, "nota_revisao": "Revisão Vivian: pergunta separada da 6.19."}, {"id": "v_6_21", "codigo": "6.21", "tipo": "texto_longo", "label": "Quais os seus três principais desafios em termos de atendimento de vendas?", "obrigatorio": false}]}, {"id": "equipe-de-corretores", "titulo": "7. Equipe de Corretores", "perguntas": [{"id": "v_7_1", "codigo": "7.1", "tipo": "texto_longo", "label": "Descreva o perfil dos melhores corretores (top 10) de vendas, com atenção ao tempo de casa, experiência no mercado imobiliário, perfil comportamental, VGV e imóveis captados dos últimos 12 meses", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: mais produtivo coletar nas entrevistas."}, {"id": "v_7_2", "codigo": "7.2", "tipo": "texto_longo", "label": "O CRECI é obrigatório para a contratação de corretores?", "obrigatorio": false, "dica": "Qual(is) perfil(is) de corretor você prioriza contratar na imobiliária (iniciantes, experientes, estagiários...)?"}, {"id": "v_7_3", "codigo": "7.3", "tipo": "texto_longo", "label": "Qual a meta mensal e/ou anual de vendas? Por corretor e/ou equipe?", "obrigatorio": false}, {"id": "v_7_4", "codigo": "7.4", "tipo": "texto_longo", "label": "Há corretor(es) especializado(s) em imóveis de algum nicho (MCMV, alto padrão, terrenos etc.)?", "obrigatorio": false}, {"id": "v_7_5", "codigo": "7.5", "tipo": "texto_longo", "label": "Qual o tipo de contrato que possui com os corretores?", "obrigatorio": false}, {"id": "v_7_6", "codigo": "7.6", "tipo": "texto_longo", "label": "Oferece alguma ajuda de custo ou benefícios para os corretores de vendas?", "obrigatorio": false}, {"id": "v_7_7", "codigo": "7.7", "tipo": "texto_longo", "label": "Qual o percentual de comissão que a sua empresa paga ao corretor vendedor, sobre o total da comissão?", "obrigatorio": false, "dica": "Existem campanhas de bonificação e/ou escalonamento que complementem este percentual?"}, {"id": "v_7_8", "codigo": "7.8", "tipo": "texto_longo", "label": "Quantos dos seus corretores fazem alguma estratégia própria de geração de leads compradores?", "obrigatorio": false}, {"id": "v_7_9", "codigo": "7.9", "tipo": "texto_longo", "label": "Os corretores se destacam por inserção em redes de relacionamento locais (igrejas, clubes, associações, práticas esportivas etc.)?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Pode ser explorado junto com a 7.8 como complemento."}, {"id": "v_7_10", "codigo": "7.10", "tipo": "texto_longo", "label": "Quantos dos seus corretores fazem alguma estratégia própria de captação ativa de imóveis? Explique.", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada."}, {"id": "v_7_11", "codigo": "7.11", "tipo": "texto_longo", "label": "Os corretores conduzem a negociação até o fim do processo de venda ou são substituídos pelo gerente em algum momento? Explique.", "obrigatorio": false}, {"id": "v_7_12", "codigo": "7.12", "tipo": "texto_longo", "label": "Os corretores geram contrato? Se não geram, quem faz isso? Explique.", "obrigatorio": false}, {"id": "v_7_13", "codigo": "7.13", "tipo": "texto_longo", "label": "Os corretores realizam a entrega de chaves? Se não fazem, quem faz isso? Explique.", "obrigatorio": false}, {"id": "v_7_14", "codigo": "7.14", "tipo": "texto_longo", "label": "Corretores cadastram todas as visitas realizadas no CRM? Se não fazem, quem faz esse cadastro?", "obrigatorio": false}, {"id": "v_7_15", "codigo": "7.15", "tipo": "texto_longo", "label": "Corretores cadastram todos os negócios fechados no CRM? Se não fazem, quem faz esse cadastro?", "obrigatorio": false}, {"id": "v_7_16", "codigo": "7.16", "tipo": "texto_longo", "label": "Quais os três principais desafios relacionados à equipe de corretores?", "obrigatorio": false}]}, {"id": "gestao-comercial", "titulo": "8. Gestão Comercial", "perguntas": [{"id": "v_8_1", "codigo": "8.1", "tipo": "numero", "label": "Quantos gestores/gerentes de equipe comercial de vendas tem na sua imobiliária?", "obrigatorio": false}, {"id": "v_8_2", "codigo": "8.2", "tipo": "texto_longo", "label": "Descreva o perfil desse(s) gestor(es)/gerente(s) comercial(is) de vendas, com atenção ao tempo de casa, experiência no mercado imobiliário e perfil comportamental.", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: mais produtivo nas entrevistas."}, {"id": "v_8_3", "codigo": "8.3", "tipo": "texto_longo", "label": "Qual o tipo de contrato que você tem com o seu gerente/gestor de vendas? (por exemplo, CLT, PJ)", "obrigatorio": false}, {"id": "v_8_4", "codigo": "8.4", "tipo": "texto_longo", "label": "Como funciona a remuneração do gestor de vendas? (fixo, variável etc.; CLT, PJ)", "obrigatorio": false, "nota_revisao": "Revisão Vivian: a pergunta original (salário fixo) foi riscada e substituída por esta, sugerida por ela."}, {"id": "v_8_5", "codigo": "8.5", "tipo": "texto_longo", "label": "Qual a comissão do gerente de vendas?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Coberta pela 8.4."}, {"id": "v_8_6", "codigo": "8.6", "tipo": "texto_longo", "label": "Qual o foco do gestor de vendas? Acompanhar funil, gestão da equipe ou realizar negociações/fechamentos?", "obrigatorio": false}, {"id": "v_8_7", "codigo": "8.7", "tipo": "texto_longo", "label": "Existem metas da equipe comercial de vendas? Se sim, explique quais.", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: repetida na aba 7 (pergunta 7.3)."}, {"id": "v_8_8", "codigo": "8.8", "tipo": "texto_longo", "label": "Há algum tipo de premiação para o caso de atingimento de meta mensal e/ou anual? Se sim, quais os prêmios?", "obrigatorio": false, "dica": "Existem regras pré-definidas para a divulgação dessas campanhas de premiação?"}, {"id": "v_8_9", "codigo": "8.9", "tipo": "texto_longo", "label": "Como é feita a divulgação/ativação da premiação?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Virou dica da 8.8."}, {"id": "v_8_10", "codigo": "8.10", "tipo": "texto_longo", "label": "Com que frequência os resultados parciais de vendas são divulgados?", "obrigatorio": false, "dica": "A gestão analisa os resultados parciais da equipe ao longo do mês nas rotinas do time?"}, {"id": "v_8_11", "codigo": "8.11", "tipo": "texto_longo", "label": "Há alguma prática de gamificação entre a equipe comercial, para incentivar novas vendas?", "obrigatorio": false}, {"id": "v_8_12", "codigo": "8.12", "tipo": "texto_longo", "label": "O time de vendas adota alguma metodologia para abordagem e mapeamento de dores do cliente? Se sim, qual?", "obrigatorio": false}, {"id": "v_8_13", "codigo": "8.13", "tipo": "texto_longo", "label": "Qual a frequência de reuniões da equipe comercial de vendas?", "obrigatorio": false}, {"id": "v_8_14", "codigo": "8.14", "tipo": "texto_longo", "label": "A equipe é estimulada a realizar exercícios práticos de demonstração de imóveis?", "obrigatorio": false, "dica": "Vocês realizam simulações de atendimento/captação com frequência na imobiliária?"}, {"id": "v_8_15", "codigo": "8.15", "tipo": "texto_longo", "label": "Como é feito o controle de propostas que estão em análise? Explique.", "obrigatorio": false, "dica": "Como é feito o acompanhamento das propostas em análise?"}, {"id": "v_8_16", "codigo": "8.16", "tipo": "texto_longo", "label": "O gestor controla o funil de vendas? Se sim, como (CRM, planilha)?", "obrigatorio": false}, {"id": "v_8_17", "codigo": "8.17", "tipo": "texto_longo", "label": "Se controla, quais são as taxas de conversão em cada etapa?", "obrigatorio": false, "dica": "Considerar o último mês ou os últimos 3 meses."}, {"id": "v_8_18", "codigo": "8.18", "tipo": "texto_longo", "label": "Quais ações adota a partir dos dados observados no funil de vendas?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada."}, {"id": "v_8_19", "codigo": "8.19", "tipo": "texto_longo", "label": "Como o gestor de vendas acompanha o funil de visitas (agendadas x realizadas)?", "obrigatorio": false}, {"id": "v_8_20", "codigo": "8.20", "tipo": "texto_longo", "label": "Como e com qual frequência o gestor de vendas dá feedbacks individuais para os corretores?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Coberta pela 8.21."}, {"id": "v_8_21", "codigo": "8.21", "tipo": "texto_longo", "label": "Como e com que frequência o gestor de vendas realiza 1:1 com os seus corretores, com o objetivo de ajudá-los no seu desenvolvimento?", "obrigatorio": false, "dica": "Como e com que frequência o gestor realiza reuniões individuais visando lapidar o desempenho do corretor?"}, {"id": "v_8_22", "codigo": "8.22", "tipo": "texto_longo", "label": "O gestor de vendas acompanha os resultados financeiros da imobiliária ou isso fica apenas no nível de diretoria?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada."}, {"id": "v_8_23", "codigo": "8.23", "tipo": "escolha_unica", "label": "Hoje, qual é o seu nível de satisfação com a atual gestão comercial?", "obrigatorio": false, "opcoes": ["Muito insatisfeito", "Insatisfeito", "Satisfeito", "Muito satisfeito"], "nota_revisao": "Revisão Vivian: substitui a pergunta original ('três principais desafios de gestão de vendas'), conforme sugestão dela."}, {"id": "v_8_24", "codigo": "8.24", "tipo": "texto_longo", "label": "Por que você escolheu esse nível de satisfação com a gestão comercial?", "obrigatorio": false, "nota_revisao": "Revisão Vivian: complemento da 8.23 ('e por quê?')."}]}, {"id": "pos-vendas", "titulo": "9. Pós-vendas", "perguntas": [{"id": "v_9_1", "codigo": "9.1", "tipo": "texto_longo", "label": "Quantas pessoas atuam no backoffice da operação de vendas? Quais são essas funções e quais as suas responsabilidades?", "obrigatorio": false, "dica": "Há um padrão de apoio no pós-vendas após a assinatura do contrato? Quem fica responsável por estas etapas?"}, {"id": "v_9_2", "codigo": "9.2", "tipo": "texto_longo", "label": "Essas pessoas acumulam outras funções? Quais?", "obrigatorio": false}, {"id": "v_9_3", "codigo": "9.3", "tipo": "texto_longo", "label": "Como é a passagem de bastão dos clientes compradores e vendedores do time comercial para o time de pós-vendas?", "obrigatorio": false}, {"id": "v_9_4", "codigo": "9.4", "tipo": "texto_longo", "label": "Os corretores emitem nota fiscal da sua parte da comissão diretamente para o vendedor ou o recebimento passa 100% pela imobiliária?", "obrigatorio": false}, {"id": "v_9_5", "codigo": "9.5", "tipo": "texto_longo", "label": "Da totalidade da comissão de intermediação da venda, quais os percentuais pagos em comissões (captador, corretor, gerente, pré-atendimento etc.)?", "obrigatorio": false}, {"id": "v_9_6", "codigo": "9.6", "tipo": "texto_longo", "label": "Qual o modelo de tributação da imobiliária (Simples, Lucro Presumido / Lucro Real)?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada."}, {"id": "v_9_7", "codigo": "9.7", "tipo": "texto_longo", "label": "Faz a geração e envio da Dimob? Como?", "obrigatorio": false}, {"id": "v_9_8", "codigo": "9.8", "tipo": "texto_curto", "label": "Qual ERP a imobiliária usa para fazer a gestão financeira?", "obrigatorio": false}, {"id": "v_9_9", "codigo": "9.9", "tipo": "texto_longo", "label": "A emissão da nota fiscal das comissões é feita de forma automática?", "obrigatorio": false}, {"id": "v_9_10", "codigo": "9.10", "tipo": "texto_longo", "label": "A imobiliária usa alguma solução de pagadoria automatizada (split automático das comissões)?", "obrigatorio": false}, {"id": "v_9_11", "codigo": "9.11", "tipo": "texto_longo", "label": "Os contratos de compra e venda são feitos pela área de pós-vendas?", "obrigatorio": false}, {"id": "v_9_12", "codigo": "9.12", "tipo": "texto_longo", "label": "Quais certidões negativas dos compradores, vendedores e imóvel a imobiliária retira na hora do fechamento do negócio?", "obrigatorio": false}, {"id": "v_9_13", "codigo": "9.13", "tipo": "texto_longo", "label": "A retirada das certidões negativas é feita manualmente, ou a imobiliária utiliza alguma ferramenta de automação (ex.: Pipeimob)?", "obrigatorio": false}, {"id": "v_9_14", "codigo": "9.14", "tipo": "texto_longo", "label": "Possui estrutura de assessoria jurídica? Clientes e corretores têm acesso a ela?", "obrigatorio": false, "nota_revisao": "Revisão Vivian: unifica as perguntas originais 9.14, 9.15 e 9.16, que foram riscadas."}, {"id": "v_9_15", "codigo": "9.15", "tipo": "texto_longo", "label": "Os clientes têm acesso direto à assessoria jurídica?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Coberta pela 9.14."}, {"id": "v_9_16", "codigo": "9.16", "tipo": "texto_longo", "label": "Os corretores têm acesso direto à assessoria jurídica ou somente o gestor de vendas?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Vivian: riscada. Coberta pela 9.14."}, {"id": "v_9_17", "codigo": "9.17", "tipo": "texto_longo", "label": "Qual a estratégia da imobiliária para entrega de brindes para o comprador e/ou vendedor após o fechamento?", "obrigatorio": false}, {"id": "v_9_18", "codigo": "9.18", "tipo": "texto_longo", "label": "Quem fica responsável pelo relacionamento com o cliente após o fechamento da venda?", "obrigatorio": false, "nota_revisao": "Revisão Vivian: a pergunta original foi riscada e substituída por esta, sugerida por ela."}, {"id": "v_9_19", "codigo": "9.19", "tipo": "texto_longo", "label": "Qual a estratégia da imobiliária para fidelizar esse cliente e fazê-lo permanecer como cliente da imobiliária?", "obrigatorio": false}, {"id": "v_9_20", "codigo": "9.20", "tipo": "texto_longo", "label": "Quais os três principais desafios da imobiliária relacionados ao pós-vendas?", "obrigatorio": false}]}, {"id": "lancamentos", "titulo": "10. Lançamentos", "perguntas": [{"id": "v_10_1", "codigo": "10.1", "tipo": "texto_longo", "label": "Há um time comercial ou pessoas dedicadas à operação de lançamentos?", "obrigatorio": false}, {"id": "v_10_2", "codigo": "10.2", "tipo": "texto_longo", "label": "Há um gestor dedicado a lançamentos?", "obrigatorio": false}, {"id": "v_10_3", "codigo": "10.3", "tipo": "numero", "label": "Quantos produtos em pré-lançamento, lançamento ou liquidação de estoque estão ativos dentro da carteira atualmente?", "obrigatorio": false}, {"id": "v_10_4", "codigo": "10.4", "tipo": "texto_longo", "label": "Quantas incorporadoras atuam em parceria com a imobiliária? Há algum incorporador ou construtor parceiro expressivo da imobiliária?", "obrigatorio": false}, {"id": "v_10_5", "codigo": "10.5", "tipo": "texto_longo", "label": "Já realizou ações de vendas com esse incorporador ou construtor? Exemplifique.", "obrigatorio": false}, {"id": "v_10_6", "codigo": "10.6", "tipo": "texto_longo", "label": "Tem abertura dos incorporadores para contribuir na formatação de produtos?", "obrigatorio": false}, {"id": "v_10_7", "codigo": "10.7", "tipo": "texto_longo", "label": "Quais as estratégias da imobiliária para realizar vendas na fase de pré-lançamentos?", "obrigatorio": false}, {"id": "v_10_8", "codigo": "10.8", "tipo": "texto_longo", "label": "Que tipos de ações de vendas realiza nos projetos COM exclusividade?", "obrigatorio": false}, {"id": "v_10_9", "codigo": "10.9", "tipo": "texto_longo", "label": "Que tipos de ações de vendas realiza nos projetos SEM exclusividade?", "obrigatorio": false}, {"id": "v_10_10", "codigo": "10.10", "tipo": "texto_longo", "label": "Fazem plantão em empreendimentos ou atividades externas?", "obrigatorio": false}, {"id": "v_10_11", "codigo": "10.11", "tipo": "texto_longo", "label": "Promove o aproveitamento da base de clientes cadastrados da imobiliária para lançamentos? Como?", "obrigatorio": false}, {"id": "v_10_12", "codigo": "10.12", "tipo": "texto_longo", "label": "Adotam alguma plataforma ou software de treinamento para produtos imobiliários?", "obrigatorio": false}, {"id": "v_10_13", "codigo": "10.13", "tipo": "texto_longo", "label": "Como realiza a apresentação e o compartilhamento de conteúdo sobre os produtos imobiliários com o time de vendas?", "obrigatorio": false}, {"id": "v_10_14", "codigo": "10.14", "tipo": "texto_longo", "label": "Compila dados sobre a velocidade de vendas de lançamentos no seu território?", "obrigatorio": false}, {"id": "v_10_15", "codigo": "10.15", "tipo": "texto_longo", "label": "Quais os três principais desafios quanto à operação de lançamentos?", "obrigatorio": false}]}]}$tpl$::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.questionarios_template WHERE segmento = 'vendas');

