SELECT 'Pré-Onboarding Consultoria — Locação (2026)', 1, true, 'locacao', $tpl${"secoes": [{"id": "qualificacao", "titulo": "1. Qualificação", "perguntas": [{"id": "l_1_1", "codigo": "1.1", "tipo": "texto_curto", "label": "Nome da imobiliária", "obrigatorio": false}, {"id": "l_1_2", "codigo": "1.2", "tipo": "texto_curto", "label": "Nome e cargo do responsável pelas respostas", "obrigatorio": false}, {"id": "l_1_3", "codigo": "1.3", "tipo": "texto_longo", "label": "Atua em outros ramos além da locação? (Ex.: Vendas, Condomínios, Consórcios)", "obrigatorio": false}, {"id": "l_1_4", "codigo": "1.4", "tipo": "texto_longo", "label": "Se atua em outros ramos, qual o grau de importância de cada um? (% aluguel, % vendas, % condomínios)", "obrigatorio": false}, {"id": "l_1_5", "codigo": "1.5", "tipo": "texto_longo", "label": "Número de sócios e suas principais funções/cargos na imobiliária", "obrigatorio": false}, {"id": "l_1_6", "codigo": "1.6", "tipo": "texto_curto", "label": "Tempo de atuação da imobiliária", "obrigatorio": false}, {"id": "l_1_7", "codigo": "1.7", "tipo": "numero", "label": "Número de sedes", "obrigatorio": false}, {"id": "l_1_8", "codigo": "1.8", "tipo": "texto_curto", "label": "Cidades de atuação", "obrigatorio": false}, {"id": "l_1_9", "codigo": "1.9", "tipo": "numero", "label": "Número de colaboradores (CLT e comissionados)", "obrigatorio": false}, {"id": "l_1_10", "codigo": "1.10", "tipo": "texto_longo", "label": "Em quais departamentos estes colaboradores se dividem?", "obrigatorio": false}, {"id": "l_1_11", "codigo": "1.11", "tipo": "texto_longo", "label": "Participa de alguma rede imobiliária? Se sim, qual?", "obrigatorio": false}, {"id": "l_1_12", "codigo": "1.12", "tipo": "numero", "label": "Número de imóveis administrados atualmente (contratos ativos)", "obrigatorio": false}, {"id": "l_1_13", "codigo": "1.13", "tipo": "texto_curto", "label": "Dos imóveis administrados, qual o percentual de contratos de locação comercial?", "obrigatorio": false}, {"id": "l_1_14", "codigo": "1.14", "tipo": "texto_longo", "label": "Já realizou compra de carteira? Se sim, qual o número de contratos adquiridos?", "obrigatorio": false}, {"id": "l_1_15", "codigo": "1.15", "tipo": "numero", "label": "Número de imóveis em divulgação (desocupados/disponíveis)", "obrigatorio": false}, {"id": "l_1_16", "codigo": "1.16", "tipo": "numero", "label": "Número MENSAL de imóveis locados (MÉDIA dos últimos 12 meses)", "obrigatorio": false}, {"id": "l_1_17", "codigo": "1.17", "tipo": "texto_curto", "label": "Ticket médio dos imóveis alugados (MÉDIA dos últimos 12 meses)", "obrigatorio": false}, {"id": "l_1_18", "codigo": "1.18", "tipo": "numero", "label": "Número MENSAL de imóveis desocupados (MÉDIA dos últimos 12 meses)", "obrigatorio": false}, {"id": "l_1_19", "codigo": "1.19", "tipo": "texto_curto", "label": "Receita advinda de todos os aluguéis cobrados no último MÊS (intermediação + administração média)", "obrigatorio": false}, {"id": "l_1_20", "codigo": "1.20", "tipo": "texto_longo", "label": "A sua imobiliária é especialista em algum tipo de produto, ticket ou nicho?", "obrigatorio": false}, {"id": "l_1_21", "codigo": "1.21", "tipo": "texto_longo", "label": "Qual o perfil médio dos seus clientes (renda, composição familiar, etc.)?", "obrigatorio": false}, {"id": "l_1_22", "codigo": "1.22", "tipo": "texto_longo", "label": "Quais são os três principais diferenciais da sua imobiliária?", "obrigatorio": false}, {"id": "l_1_23", "codigo": "1.23", "tipo": "texto_longo", "label": "Como você gostaria que a sua imobiliária fosse reconhecida?", "obrigatorio": false}, {"id": "l_1_24", "codigo": "1.24", "tipo": "texto_longo", "label": "Possui missão, visão e valores? Se sim, quais são?", "obrigatorio": false}, {"id": "l_1_25", "codigo": "1.25", "tipo": "texto_longo", "label": "Quais são as três principais dores ou fatores que impedem o crescimento da imobiliária?", "obrigatorio": false}]}, {"id": "mercado", "titulo": "2. Mercado", "perguntas": [{"id": "l_2_1", "codigo": "2.1", "tipo": "texto_longo", "label": "Qual o tamanho do mercado em que atua (número de imóveis em divulgação)?", "obrigatorio": false}, {"id": "l_2_2", "codigo": "2.2", "tipo": "texto_longo", "label": "Quem são os seus principais concorrentes?", "obrigatorio": false}, {"id": "l_2_3", "codigo": "2.3", "tipo": "texto_longo", "label": "Como você avalia os seus concorrentes? (pontos fortes e fracos)", "obrigatorio": false}, {"id": "l_2_4", "codigo": "2.4", "tipo": "texto_longo", "label": "Qual a sua participação (%) dentro do mercado em que atua?", "obrigatorio": false}, {"id": "l_2_5", "codigo": "2.5", "tipo": "sim_nao", "label": "A exclusividade é uma prática comum no seu mercado de locação?", "obrigatorio": false}, {"id": "l_2_6", "codigo": "2.6", "tipo": "texto_longo", "label": "Você realiza ou já realizou cliente oculto nos seus concorrentes?", "obrigatorio": false}, {"id": "l_2_7", "codigo": "2.7", "tipo": "texto_curto", "label": "Qual a taxa de administração comumente praticada no seu mercado?", "obrigatorio": false}, {"id": "l_2_8", "codigo": "2.8", "tipo": "texto_curto", "label": "Qual a taxa de intermediação comumente praticada no seu mercado?", "obrigatorio": false}, {"id": "l_2_9", "codigo": "2.9", "tipo": "texto_longo", "label": "Com qual frequência vocês monitoram ou analisam as pesquisas que contêm dados de população e domicílios alugados da sua cidade?", "obrigatorio": false}, {"id": "l_2_10", "codigo": "2.10", "tipo": "texto_longo", "label": "Quais os três principais desafios em relação ao seu mercado de atuação?", "obrigatorio": false}]}, {"id": "gestao-de-pessoas", "titulo": "3. Gestão de Pessoas", "perguntas": [{"id": "l_3_1", "codigo": "3.1", "tipo": "numero", "label": "Qual o número total de colaboradores (CLT e PJ) da operação de locação?", "obrigatorio": false}, {"id": "l_3_2", "codigo": "3.2", "tipo": "texto_longo", "label": "Tem uma pessoa dedicada ao RH? Qual o perfil dela? Nome e cargo.", "obrigatorio": false}, {"id": "l_3_3", "codigo": "3.3", "tipo": "texto_longo", "label": "Qual o principal papel dessa pessoa? Departamento pessoal, recrutamento, treinamento ou outro?", "obrigatorio": false}, {"id": "l_3_4", "codigo": "3.4", "tipo": "texto_longo", "label": "Possui organograma da operação de locação?", "obrigatorio": false}, {"id": "l_3_5", "codigo": "3.5", "tipo": "texto_longo", "label": "Possui descritivo de cargos?", "obrigatorio": false}, {"id": "l_3_6", "codigo": "3.6", "tipo": "texto_longo", "label": "Possui processos e procedimentos mapeados, escritos e difundidos na operação?", "obrigatorio": false}, {"id": "l_3_7", "codigo": "3.7", "tipo": "texto_longo", "label": "Qual o principal canal de atração de novos colaboradores? (por exemplo, LinkedIn, indicação, Instagram, eventos)", "obrigatorio": false}, {"id": "l_3_8", "codigo": "3.8", "tipo": "texto_longo", "label": "A imobiliária realiza, regularmente (trimestral, semestral, anual), avaliação de desempenho das equipes? Como ela é feita?", "obrigatorio": false}, {"id": "l_3_9", "codigo": "3.9", "tipo": "texto_longo", "label": "Quais ações de retenção de talentos são realizadas e com qual frequência?", "obrigatorio": false}, {"id": "l_3_10", "codigo": "3.10", "tipo": "texto_longo", "label": "Quais os três principais desafios em termos de gestão de pessoas/equipe relacionados à operação de locação?", "obrigatorio": false}]}, {"id": "marketing", "titulo": "4. Marketing", "perguntas": [{"id": "l_4_1", "codigo": "4.1", "tipo": "texto_longo", "label": "Como é a estrutura de marketing da imobiliária? Agência externa, time interno? Se tiver, qual o tamanho do time interno?", "obrigatorio": false}, {"id": "l_4_2", "codigo": "4.2", "tipo": "sim_nao", "label": "O nome da sua marca é registrado?", "obrigatorio": false}, {"id": "l_4_3", "codigo": "4.3", "tipo": "texto_longo", "label": "Quem é o responsável pela estratégia/planejamento de marketing?", "obrigatorio": false}, {"id": "l_4_4", "codigo": "4.4", "tipo": "texto_longo", "label": "Qual a sua estratégia de posicionamento hoje? (Padrão do imóvel, região de atuação, etc.)", "obrigatorio": false}, {"id": "l_4_5", "codigo": "4.5", "tipo": "texto_longo", "label": "Você possui uma estratégia de comunicação interna?", "obrigatorio": false}, {"id": "l_4_6", "codigo": "4.6", "tipo": "texto_longo", "label": "Quanto você investe mensalmente considerando mídia online (Meta Ads, Google Ads, LinkedIn Ads, etc.)?", "obrigatorio": false}, {"id": "l_4_7", "codigo": "4.7", "tipo": "texto_longo", "label": "Quais são os objetivos das campanhas em Facebook e Instagram: alcance, tráfego no site e/ou geração de cadastros?", "obrigatorio": false}, {"id": "l_4_8", "codigo": "4.8", "tipo": "texto_longo", "label": "As campanhas de mídia online são separadas por funil? Existem campanhas para imóveis específicos?", "obrigatorio": false}, {"id": "l_4_9", "codigo": "4.9", "tipo": "texto_longo", "label": "Os criativos das campanhas são atualizados com que frequência?", "obrigatorio": false}, {"id": "l_4_10", "codigo": "4.10", "tipo": "texto_longo", "label": "O que é considerado conversão? (lead, visita, contato WhatsApp)", "obrigatorio": false}, {"id": "l_4_11", "codigo": "4.11", "tipo": "texto_longo", "label": "Qual a origem dos leads que mais geram locação (Meta Ads, Google Ads, Site Orgânico, WhatsApp, etc.)?", "obrigatorio": false, "nota_revisao": "Revisão Cupola (Claude): o original dizia 'geram venda'; ajustado para locação."}, {"id": "l_4_12", "codigo": "4.12", "tipo": "texto_longo", "label": "Em quais portais imobiliários está presente?", "obrigatorio": false}, {"id": "l_4_13", "codigo": "4.13", "tipo": "texto_longo", "label": "Qual o investimento mensal em portais? Descreva o investimento em cada portal que você anuncia.", "obrigatorio": false}, {"id": "l_4_14", "codigo": "4.14", "tipo": "texto_longo", "label": "Os portais imobiliários estão integrados ao seu sistema de gestão de imóveis para envio dos anúncios de forma automatizada?", "obrigatorio": false}, {"id": "l_4_15", "codigo": "4.15", "tipo": "texto_longo", "label": "As campanhas de mídia online e os portais imobiliários estão integrados ao seu sistema de gestão de leads para recebimento automático dentro do CRM?", "obrigatorio": false}, {"id": "l_4_16", "codigo": "4.16", "tipo": "texto_longo", "label": "Quanto você investe mensalmente em ações e mídia offline (outdoor, flyers, folders, rádio, revista, jornal, televisão, parcerias de experiência, etc.)?", "obrigatorio": false}, {"id": "l_4_17", "codigo": "4.17", "tipo": "texto_longo", "label": "Quantos leads (contatos novos) foram gerados nos últimos 12 meses?", "obrigatorio": false}, {"id": "l_4_18", "codigo": "4.18", "tipo": "texto_longo", "label": "Responde regularmente o Google Meu Negócio e o Reclame Aqui?", "obrigatorio": false}, {"id": "l_4_19", "codigo": "4.19", "tipo": "texto_longo", "label": "Realiza disparos de e-mails regularmente para a base de leads? Se sim, qual a frequência e qual software usa?", "obrigatorio": false}, {"id": "l_4_20", "codigo": "4.20", "tipo": "texto_curto", "label": "Qual a plataforma do site (WordPress, Loft, Universal, Rocket, etc.)?", "obrigatorio": false}, {"id": "l_4_21", "codigo": "4.21", "tipo": "texto_longo", "label": "Como você avalia a experiência do seu site hoje (rápido, fácil de encontrar os imóveis, possui informações suficientes, bonito)?", "obrigatorio": false}, {"id": "l_4_22", "codigo": "4.22", "tipo": "texto_longo", "label": "Você está satisfeito com o tráfego orgânico do seu site? Quantas palavras-chave possui nas 10 primeiras posições?", "obrigatorio": false}, {"id": "l_4_23", "codigo": "4.23", "tipo": "texto_longo", "label": "Existe estratégia de SEO definida hoje?", "obrigatorio": false}, {"id": "l_4_24", "codigo": "4.24", "tipo": "texto_longo", "label": "Possui blog ativo? Se sim, é atualizado com qual frequência?", "obrigatorio": false}, {"id": "l_4_25", "codigo": "4.25", "tipo": "texto_longo", "label": "A imobiliária incentiva que os corretores façam mídia por conta própria em portais e redes sociais?", "obrigatorio": false}, {"id": "l_4_26", "codigo": "4.26", "tipo": "texto_longo", "label": "O que já funciona bem no marketing da sua imobiliária?", "obrigatorio": false}, {"id": "l_4_27", "codigo": "4.27", "tipo": "texto_longo", "label": "Quais são os três principais desafios relacionados ao marketing na sua imobiliária?", "obrigatorio": false}]}, {"id": "captacao", "titulo": "5. Captação", "perguntas": [{"id": "l_5_1", "codigo": "5.1", "tipo": "numero", "label": "Média MENSAL de imóveis captados nos últimos 12 meses", "obrigatorio": false}, {"id": "l_5_2", "codigo": "5.2", "tipo": "numero", "label": "Qual a meta de captação de imóveis por mês?", "obrigatorio": false}, {"id": "l_5_3", "codigo": "5.3", "tipo": "texto_longo", "label": "Existe uma área ou pessoa 100% dedicada à captação? Quantas pessoas?", "obrigatorio": false}, {"id": "l_5_3b", "codigo": "5.3b", "tipo": "texto_longo", "label": "Descreva o perfil dos captadores, com atenção ao tempo de casa, experiência no mercado e média de imóveis captados por mês", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): mesmo critério da Vivian na aba de corretores de Vendas (7.1): perfil individual é melhor coletado na entrevista presencial."}, {"id": "l_5_4", "codigo": "5.4", "tipo": "texto_longo", "label": "Se não existe setor, quem atende as captações receptivas?", "obrigatorio": false}, {"id": "l_5_5", "codigo": "5.5", "tipo": "texto_longo", "label": "Quem faz a gestão dos captadores? Como e com qual frequência é feito o acompanhamento da equipe de captação?", "obrigatorio": false}, {"id": "l_5_6", "codigo": "5.6", "tipo": "texto_longo", "label": "Como é a remuneração da captação (CLT, fixo, variável)?", "obrigatorio": false}, {"id": "l_5_7", "codigo": "5.7", "tipo": "texto_curto", "label": "Qual o percentual de comissão do captador sobre a intermediação?", "obrigatorio": false}, {"id": "l_5_8", "codigo": "5.8", "tipo": "texto_longo", "label": "Todos os colaboradores podem captar? Qual a remuneração?", "obrigatorio": false}, {"id": "l_5_9", "codigo": "5.9", "tipo": "texto_longo", "label": "Usa algum CRM e/ou sistema de gestão de imóveis? Qual?", "obrigatorio": false}, {"id": "l_5_10", "codigo": "5.10", "tipo": "texto_longo", "label": "Como os captadores trazem imóveis sem depender de receptivo?", "obrigatorio": false}, {"id": "l_5_11", "codigo": "5.11", "tipo": "texto_longo", "label": "Existe um direcionamento claro de imóveis desejados para a captação (tipologias, preços, bairros)?", "obrigatorio": false}, {"id": "l_5_12", "codigo": "5.12", "tipo": "texto_longo", "label": "Quem faz e como é feita a avaliação dos imóveis captados (ferramentas, critérios)?", "obrigatorio": false, "nota_revisao": "Revisão Cupola (Claude): unifica as perguntas 5.12 e 5.13 originais, no mesmo critério aplicado por Vivian às perguntas de avaliação em Vendas (5.8/5.9)."}, {"id": "l_5_13", "codigo": "5.13", "tipo": "texto_longo", "label": "Como é feita a avaliação (ferramentas, critérios)?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): coberta pela 5.12 unificada."}, {"id": "l_5_14", "codigo": "5.14", "tipo": "texto_curto", "label": "Qual o percentual de imóveis COM exclusividade na carteira?", "obrigatorio": false}, {"id": "l_5_15", "codigo": "5.15", "tipo": "texto_longo", "label": "Oferece aluguel garantido? Qual a taxa nesse caso?", "obrigatorio": false}, {"id": "l_5_16", "codigo": "5.16", "tipo": "texto_curto", "label": "Taxa média de administração da carteira atual", "obrigatorio": false}, {"id": "l_5_17", "codigo": "5.17", "tipo": "texto_curto", "label": "Taxa de administração cobrada de NOVOS clientes", "obrigatorio": false}, {"id": "l_5_18", "codigo": "5.18", "tipo": "texto_curto", "label": "Taxa de intermediação cobrada de NOVOS clientes", "obrigatorio": false}, {"id": "l_5_19", "codigo": "5.19", "tipo": "texto_longo", "label": "Existe algum material de suporte para apresentação e auxílio do captador na venda dos serviços (PDF, vídeo, pasta etc.)?", "obrigatorio": false}, {"id": "l_5_20", "codigo": "5.20", "tipo": "texto_longo", "label": "Há programa de parceria com terceiros (zeladores, porteiros)? Como funciona?", "obrigatorio": false}, {"id": "l_5_21", "codigo": "5.21", "tipo": "texto_longo", "label": "Quem comunica o proprietário sobre propostas e disponibilidade no site?", "obrigatorio": false}, {"id": "l_5_22", "codigo": "5.22", "tipo": "texto_longo", "label": "Utiliza software de enriquecimento de dados (Eemóvel, Procob, Assertiva) para apoiar os captadores na prospecção?", "obrigatorio": false}, {"id": "l_5_23", "codigo": "5.23", "tipo": "texto_longo", "label": "Quais os três principais desafios em termos de captação?", "obrigatorio": false}]}, {"id": "pre-atendimento", "titulo": "6. Pré-atendimento", "perguntas": [{"id": "l_6_1", "codigo": "6.1", "tipo": "texto_longo", "label": "Quem faz o primeiro atendimento (SDR/pré-atendimento ou corretores/atendentes)?", "obrigatorio": false}, {"id": "l_6_2", "codigo": "6.2", "tipo": "sim_nao", "label": "Divulga número de WhatsApp exclusivo para locação?", "obrigatorio": false}, {"id": "l_6_3", "codigo": "6.3", "tipo": "texto_curto", "label": "Qual o CRM utilizado para registro dos leads?", "obrigatorio": false}, {"id": "l_6_4", "codigo": "6.4", "tipo": "texto_longo", "label": "Utiliza uma ferramenta omnichannel para centralizar os atendimentos comerciais?", "obrigatorio": false, "nota_revisao": "Revisão Cupola (Claude): o original misturava omnichannel e IA; IA ficou na 6.5."}, {"id": "l_6_5", "codigo": "6.5", "tipo": "texto_longo", "label": "Utiliza alguma ferramenta de IA para fazer qualificação no primeiro atendimento?", "obrigatorio": false}, {"id": "l_6_6", "codigo": "6.6", "tipo": "texto_longo", "label": "Qual o objetivo desse primeiro atendimento? (velocidade na resposta, entendimento de demanda, qualificação do lead)", "obrigatorio": false}, {"id": "l_6_7", "codigo": "6.7", "tipo": "texto_longo", "label": "Existe script ou metodologia de qualificação de leads?", "obrigatorio": false}, {"id": "l_6_8", "codigo": "6.8", "tipo": "texto_longo", "label": "Como chegam os contatos de portais imobiliários (e-mail, dentro do CRM etc.)?", "obrigatorio": false}, {"id": "l_6_9", "codigo": "6.9", "tipo": "texto_longo", "label": "Como chegam os contatos do site da imobiliária (e-mail, dentro do CRM etc.)?", "obrigatorio": false}, {"id": "l_6_10", "codigo": "6.10", "tipo": "texto_longo", "label": "Todas as leads recebidas ou apenas as que respondem são cadastradas em CRM, outro sistema ou planilha?", "obrigatorio": false}, {"id": "l_6_11", "codigo": "6.11", "tipo": "texto_longo", "label": "Como funciona a distribuição das leads após a qualificação?", "obrigatorio": false}, {"id": "l_6_12", "codigo": "6.12", "tipo": "texto_longo", "label": "Existe prazo máximo para retorno? Como é controlado?", "obrigatorio": false}, {"id": "l_6_13", "codigo": "6.13", "tipo": "texto_longo", "label": "Em que momento a visita é ofertada? O agendamento das visitas é registrado no CRM?", "obrigatorio": false}, {"id": "l_6_14", "codigo": "6.14", "tipo": "numero", "label": "Quantas tentativas de contato são feitas com o lead até o seu descarte?", "obrigatorio": false}, {"id": "l_6_15", "codigo": "6.15", "tipo": "texto_longo", "label": "Qual trabalho é realizado com as leads descartadas ou não aproveitadas?", "obrigatorio": false, "nota_revisao": "Revisão Cupola (Claude): separada da pergunta de resgate, seguindo o pedido da Vivian em Vendas (6.19)."}, {"id": "l_6_16", "codigo": "6.16", "tipo": "texto_longo", "label": "Como é feito o trabalho de resgate dessas leads?", "obrigatorio": false}, {"id": "l_6_17", "codigo": "6.17", "tipo": "texto_longo", "label": "Em que momento do atendimento a imobiliária explica as garantias locatícias aceitas? Como isso é explicado para o cliente?", "obrigatorio": false}, {"id": "l_6_18", "codigo": "6.18", "tipo": "texto_longo", "label": "Existe alguma orientação para os pré-atendentes ou atendentes em relação a garantias mais estratégicas para a imobiliária?", "obrigatorio": false}, {"id": "l_6_19", "codigo": "6.19", "tipo": "texto_longo", "label": "Liste as 5 principais garantias locatícias aceitas e o percentual de cada uma na carteira atual", "obrigatorio": false}, {"id": "l_6_20", "codigo": "6.20", "tipo": "texto_longo", "label": "Quais os três principais desafios no pré-atendimento?", "obrigatorio": false}]}, {"id": "atendimento-comercial", "titulo": "7. Atendimento Comercial", "perguntas": [{"id": "l_7_1", "codigo": "7.1", "tipo": "texto_longo", "label": "Descreva o perfil dos corretores/atendentes de locação, com atenção ao tempo de casa, experiência no mercado imobiliário, perfil comportamental, e média de VGL e número de contratos fechados por mês nos últimos 12 meses", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): mesmo critério da Vivian em Vendas (7.1): perfil individual é melhor coletado na entrevista presencial."}, {"id": "l_7_2", "codigo": "7.2", "tipo": "texto_longo", "label": "Qual o modelo de contratação dos corretores/atendentes de locação? (CLT, PJ)", "obrigatorio": false}, {"id": "l_7_3", "codigo": "7.3", "tipo": "texto_longo", "label": "Qual a meta mensal de locações por corretor/atendente?", "obrigatorio": false}, {"id": "l_7_4", "codigo": "7.4", "tipo": "texto_longo", "label": "Como é a remuneração (fixo + comissão)?", "obrigatorio": false}, {"id": "l_7_5", "codigo": "7.5", "tipo": "texto_longo", "label": "Existe algum tipo de premiação por atingimento de metas?", "obrigatorio": false}, {"id": "l_7_6", "codigo": "7.6", "tipo": "texto_longo", "label": "Como é feito o controle de visitas (agendadas x realizadas)?", "obrigatorio": false}, {"id": "l_7_7", "codigo": "7.7", "tipo": "texto_longo", "label": "Quem faz e como é feita a análise de crédito de potenciais locatários? Que ferramentas utilizam?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): duplicada pelas perguntas 9.2 e 9.3, que detalham a análise por tipo de garantia."}, {"id": "l_7_8", "codigo": "7.8", "tipo": "texto_longo", "label": "Quem é o responsável e como é feita a geração de contratos de locação? (modelo no sistema, documento do Word)", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): duplicada pela 9.5."}, {"id": "l_7_9", "codigo": "7.9", "tipo": "texto_curto", "label": "Qual a taxa de conversão de visitas para propostas?", "obrigatorio": false}, {"id": "l_7_10", "codigo": "7.10", "tipo": "texto_longo", "label": "Os corretores/atendentes realizam a entrega de chaves? Se não fazem, quem faz isso? Explique.", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): duplicada pela 9.6."}, {"id": "l_7_11", "codigo": "7.11", "tipo": "texto_longo", "label": "Quais os principais desafios da equipe comercial?", "obrigatorio": false}]}, {"id": "gestao-comercial", "titulo": "8. Gestão Comercial", "perguntas": [{"id": "l_8_1", "codigo": "8.1", "tipo": "texto_longo", "label": "Há um gestor/gerente comercial exclusivo para o comercial da locação ou ele se divide entre comercial e administrativo?", "obrigatorio": false}, {"id": "l_8_2", "codigo": "8.2", "tipo": "texto_longo", "label": "Se sim, descreva o perfil do gestor/gerente comercial de locação, com atenção ao tempo de casa, experiência no mercado imobiliário e perfil comportamental.", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): mesmo critério da Vivian em Vendas (8.2): melhor nas entrevistas."}, {"id": "l_8_3", "codigo": "8.3", "tipo": "texto_longo", "label": "Qual o tipo de contrato que você tem com o seu gerente/gestor comercial de locação? (por exemplo, CLT, PJ)", "obrigatorio": false, "nota_revisao": "Revisão Cupola (Claude): o original dizia 'gerente/gestor de vendas'; ajustado para locação."}, {"id": "l_8_4", "codigo": "8.4", "tipo": "texto_longo", "label": "Como funciona a remuneração do gestor comercial de locação? (fixo, variável etc.; em cima do que a comissão é calculada)", "obrigatorio": false, "nota_revisao": "Revisão Cupola (Claude): unifica as perguntas originais de salário fixo (8.4) e comissão (8.5), como a Vivian fez em Vendas (8.4)."}, {"id": "l_8_5", "codigo": "8.5", "tipo": "texto_longo", "label": "Qual a comissão do gerente de locação? Em cima do que ela é calculada?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): coberta pela 8.4 unificada."}, {"id": "l_8_6", "codigo": "8.6", "tipo": "texto_longo", "label": "Qual o foco do gestor comercial de locação? Acompanhar funil, gestão da equipe ou realizar negociações/fechamentos?", "obrigatorio": false}, {"id": "l_8_7", "codigo": "8.7", "tipo": "texto_longo", "label": "Qual a frequência de reuniões da equipe comercial de locação? O time de captação também participa desses encontros?", "obrigatorio": false}, {"id": "l_8_8", "codigo": "8.8", "tipo": "texto_longo", "label": "Qual a frequência de reuniões individuais do gestor comercial de locação com cada integrante da equipe?", "obrigatorio": false}, {"id": "l_8_9", "codigo": "8.9", "tipo": "texto_longo", "label": "A equipe é estimulada a realizar exercícios práticos de demonstração de imóveis?", "obrigatorio": false}, {"id": "l_8_10", "codigo": "8.10", "tipo": "texto_longo", "label": "O gestor controla o funil de locação? Se sim, como (CRM, planilha)?", "obrigatorio": false}, {"id": "l_8_11", "codigo": "8.11", "tipo": "texto_longo", "label": "Se controla, quais são as taxas de conversão em cada etapa?", "obrigatorio": false}, {"id": "l_8_12", "codigo": "8.12", "tipo": "texto_longo", "label": "Quais ações adota a partir dos dados observados no funil de locação?", "obrigatorio": false}, {"id": "l_8_13", "codigo": "8.13", "tipo": "texto_longo", "label": "Como o gestor comercial de locação acompanha o funil de visitas (agendadas x realizadas)?", "obrigatorio": false}, {"id": "l_8_14", "codigo": "8.14", "tipo": "texto_longo", "label": "Como e com qual frequência o gestor comercial de locação dá feedbacks para a equipe comercial?", "obrigatorio": false}, {"id": "l_8_15", "codigo": "8.15", "tipo": "texto_longo", "label": "Como e com que frequência o gestor comercial de locação realiza 1:1 com os seus liderados, com o objetivo de ajudá-los no seu desenvolvimento?", "obrigatorio": false}, {"id": "l_8_16", "codigo": "8.16", "tipo": "texto_longo", "label": "Quais os três principais desafios de gestão comercial de locação na sua imobiliária?", "obrigatorio": false}]}, {"id": "onboarding-de-locatarios", "titulo": "9. Onboarding de Locatários", "perguntas": [{"id": "l_9_1", "codigo": "9.1", "tipo": "texto_longo", "label": "Qual a documentação exigida para o candidato a locatário?", "obrigatorio": false}, {"id": "l_9_2", "codigo": "9.2", "tipo": "texto_longo", "label": "Quem faz e como faz a análise e aprovação de crédito do candidato a locatário com a garantia fiador?", "obrigatorio": false}, {"id": "l_9_3", "codigo": "9.3", "tipo": "texto_longo", "label": "Quem faz e como faz a análise e aprovação de crédito do candidato a locatário com garantias onerosas (seguro fiança, fiança onerosa, título de capitalização)?", "obrigatorio": false}, {"id": "l_9_4", "codigo": "9.4", "tipo": "texto_curto", "label": "Qual o tempo médio entre a aprovação do cadastro e a entrega de chaves?", "obrigatorio": false}, {"id": "l_9_5", "codigo": "9.5", "tipo": "texto_longo", "label": "Quem elabora o contrato e como é feita a minuta? Utilizam ferramentas do ERP ou documentos do Word/Google Docs?", "obrigatorio": false}, {"id": "l_9_6", "codigo": "9.6", "tipo": "texto_longo", "label": "Quem faz a entrega de chaves para o locatário?", "obrigatorio": false}, {"id": "l_9_7", "codigo": "9.7", "tipo": "texto_longo", "label": "O inquilino recebe algo na entrega de chaves? (brindes, manual, etc.)", "obrigatorio": false}, {"id": "l_9_8", "codigo": "9.8", "tipo": "texto_longo", "label": "Como é feita a passagem de bastão interna do time comercial para o time administrativo de locação?", "obrigatorio": false}, {"id": "l_9_9", "codigo": "9.9", "tipo": "texto_curto", "label": "Qual ERP a imobiliária usa para gestão da carteira?", "obrigatorio": false}, {"id": "l_9_10", "codigo": "9.10", "tipo": "texto_longo", "label": "Como é feita a comunicação com o proprietário no momento do fechamento da locação?", "obrigatorio": false}, {"id": "l_9_11", "codigo": "9.11", "tipo": "texto_longo", "label": "Quais os três principais desafios na área de onboarding do locatário?", "obrigatorio": false}]}, {"id": "atendimento-pos-locacao", "titulo": "10. Atendimento Pós-locação", "perguntas": [{"id": "l_10_1", "codigo": "10.1", "tipo": "texto_longo", "label": "Qual a estrutura do administrativo? Trabalham com gestores de carteiras, setores específicos ou misto?", "obrigatorio": false}, {"id": "l_10_2", "codigo": "10.2", "tipo": "texto_longo", "label": "Quantas pessoas trabalham na área administrativa? Como elas se dividem (setores, equipes)?", "obrigatorio": false}, {"id": "l_10_3", "codigo": "10.3", "tipo": "texto_longo", "label": "Quais as principais responsabilidades destas equipes?", "obrigatorio": false}, {"id": "l_10_4", "codigo": "10.4", "tipo": "texto_longo", "label": "Qual a estratégia de fidelização dos proprietários?", "obrigatorio": false}, {"id": "l_10_5", "codigo": "10.5", "tipo": "texto_longo", "label": "Quais as metas do time administrativo?", "obrigatorio": false}, {"id": "l_10_6", "codigo": "10.6", "tipo": "texto_longo", "label": "Existe alguma ferramenta de gestão de chamados? Qual?", "obrigatorio": false}, {"id": "l_10_7", "codigo": "10.7", "tipo": "texto_longo", "label": "Todos os atendimentos administrativos são monitorados? Quantos chamados a imobiliária recebe, em média, por mês?", "obrigatorio": false}, {"id": "l_10_8", "codigo": "10.8", "tipo": "texto_curto", "label": "Qual o prazo máximo de primeira resposta a chamados?", "obrigatorio": false}, {"id": "l_10_9", "codigo": "10.9", "tipo": "texto_longo", "label": "Como é feito o monitoramento da qualidade e satisfação dos atendimentos administrativos/chamados?", "obrigatorio": false}, {"id": "l_10_10", "codigo": "10.10", "tipo": "texto_longo", "label": "Quais os principais desafios no pós-locação?", "obrigatorio": false}]}, {"id": "vistorias", "titulo": "11. Vistorias", "perguntas": [{"id": "l_11_1", "codigo": "11.1", "tipo": "texto_longo", "label": "Quem realiza as vistorias de entrada? (equipe interna ou terceirizada)", "obrigatorio": false}, {"id": "l_11_2", "codigo": "11.2", "tipo": "texto_longo", "label": "Descreva o processo de vistoria de entrada (ferramentas, etapas).", "obrigatorio": false}, {"id": "l_11_3", "codigo": "11.3", "tipo": "texto_longo", "label": "Quem realiza as vistorias de saída? (equipe interna ou terceirizada)", "obrigatorio": false}, {"id": "l_11_4", "codigo": "11.4", "tipo": "texto_longo", "label": "Como é feita a conferência da vistoria de saída?", "obrigatorio": false}, {"id": "l_11_5", "codigo": "11.5", "tipo": "texto_longo", "label": "A negociação de reparos na rescisão de contratos é feita pelo vistoriador ou por uma equipe interna?", "obrigatorio": false}, {"id": "l_11_6", "codigo": "11.6", "tipo": "texto_longo", "label": "Cobra taxa de vistorias? De quem e quanto?", "obrigatorio": false}, {"id": "l_11_7", "codigo": "11.7", "tipo": "texto_longo", "label": "Utiliza algum aplicativo de vistoria? Qual?", "obrigatorio": false}, {"id": "l_11_8", "codigo": "11.8", "tipo": "texto_longo", "label": "Como é feito o monitoramento das contestações de vistoria de entrada? Existe um indicador disso?", "obrigatorio": false}, {"id": "l_11_9", "codigo": "11.9", "tipo": "texto_longo", "label": "Quais os três principais desafios em relação a vistorias (de entrada e/ou de saída)?", "obrigatorio": false}]}, {"id": "manutencao", "titulo": "12. Manutenção", "perguntas": [{"id": "l_12_1", "codigo": "12.1", "tipo": "texto_longo", "label": "Quem faz a gestão da manutenção (equipe interna ou terceirizada)?", "obrigatorio": false}, {"id": "l_12_2", "codigo": "12.2", "tipo": "texto_longo", "label": "Existe uma equipe interna de prestadores, são prestadores terceirizados ou a imobiliária tem parceria com empresas como a Refera que fazem toda a gestão da manutenção?", "obrigatorio": false}, {"id": "l_12_3", "codigo": "12.3", "tipo": "texto_longo", "label": "Quantos chamados de manutenção a imobiliária recebe, em média?", "obrigatorio": false}, {"id": "l_12_4", "codigo": "12.4", "tipo": "texto_longo", "label": "Quais os 3 principais tipos de chamados de manutenção que a imobiliária recebe? (por exemplo, infiltração, elétrica etc.)", "obrigatorio": false}, {"id": "l_12_5", "codigo": "12.5", "tipo": "texto_longo", "label": "Como o inquilino solicita reparos (app, WhatsApp, e-mail)?", "obrigatorio": false}, {"id": "l_12_6", "codigo": "12.6", "tipo": "texto_longo", "label": "Descreva brevemente o processo de chamados de manutenção, da abertura do chamado à finalização.", "obrigatorio": false}, {"id": "l_12_7", "codigo": "12.7", "tipo": "texto_longo", "label": "Como é o fluxo de aprovação de orçamentos com o proprietário?", "obrigatorio": false}, {"id": "l_12_8", "codigo": "12.8", "tipo": "texto_longo", "label": "A imobiliária possui prestadores de serviço parceiros?", "obrigatorio": false}, {"id": "l_12_9", "codigo": "12.9", "tipo": "texto_longo", "label": "Quais as metas da equipe de manutenção?", "obrigatorio": false}, {"id": "l_12_10", "codigo": "12.10", "tipo": "texto_longo", "label": "Quais as principais reclamações dos clientes em relação à área de manutenção?", "obrigatorio": false}, {"id": "l_12_11", "codigo": "12.11", "tipo": "texto_longo", "label": "Quais são os três principais desafios relacionados à área de manutenção?", "obrigatorio": false}]}, {"id": "rescisao", "titulo": "13. Rescisão", "perguntas": [{"id": "l_13_1", "codigo": "13.1", "tipo": "texto_longo", "label": "Quem e quantas são as pessoas envolvidas na área de rescisão?", "obrigatorio": false}, {"id": "l_13_2", "codigo": "13.2", "tipo": "numero", "label": "Quantos avisos de desocupação a imobiliária recebe em um mês normal?", "obrigatorio": false}, {"id": "l_13_3", "codigo": "13.3", "tipo": "texto_longo", "label": "Como acontece o processo de desocupação, desde o aviso até a efetiva entrega do imóvel?", "obrigatorio": false}, {"id": "l_13_4", "codigo": "13.4", "tipo": "texto_longo", "label": "Quem e em que momento do processo a vistoria de saída é agendada?", "obrigatorio": false}, {"id": "l_13_5", "codigo": "13.5", "tipo": "texto_longo", "label": "Quais as metas do time de desocupação?", "obrigatorio": false}, {"id": "l_13_6", "codigo": "13.6", "tipo": "texto_longo", "label": "Em que momento o imóvel que entra em processo de desocupação é recaptado pela imobiliária? Como é esse processo?", "obrigatorio": false}, {"id": "l_13_7", "codigo": "13.7", "tipo": "texto_longo", "label": "Como o time de atendimento comercial fica sabendo de imóveis desocupados para trabalhar uma nova locação?", "obrigatorio": false}, {"id": "l_13_8", "codigo": "13.8", "tipo": "texto_longo", "label": "Como a imobiliária monitora as contestações de vistoria de saída feitas pelos proprietários? O que é feito com isso?", "obrigatorio": false}, {"id": "l_13_9", "codigo": "13.9", "tipo": "texto_curto", "label": "Qual sistema de gestão é utilizado para gerir os avisos de desocupação?", "obrigatorio": false}, {"id": "l_13_10", "codigo": "13.10", "tipo": "texto_longo", "label": "Quais os três principais desafios relacionados à área de rescisão de contratos?", "obrigatorio": false}]}, {"id": "financeiro", "titulo": "14. Financeiro", "perguntas": [{"id": "l_14_1", "codigo": "14.1", "tipo": "texto_longo", "label": "Quem é o responsável pelo financeiro da locação? Além do financeiro da locação, essa pessoa realiza atividades para outra área?", "obrigatorio": false}, {"id": "l_14_2", "codigo": "14.2", "tipo": "texto_longo", "label": "Quais as atividades do financeiro da locação?", "obrigatorio": false}, {"id": "l_14_3", "codigo": "14.3", "tipo": "texto_longo", "label": "Existe um gestor financeiro dedicado ou a equipe financeira é gerida pelo gestor administrativo?", "obrigatorio": false}, {"id": "l_14_4", "codigo": "14.4", "tipo": "texto_longo", "label": "A gestão financeira é feita dentro do mesmo ERP que gere os contratos ou tem outra ferramenta?", "obrigatorio": false}, {"id": "l_14_5", "codigo": "14.5", "tipo": "texto_longo", "label": "Como é feita a análise de DRE para avaliar os resultados da operação?", "obrigatorio": false}, {"id": "l_14_6", "codigo": "14.6", "tipo": "texto_longo", "label": "Como é organizado o fluxo de caixa da imobiliária?", "obrigatorio": false}, {"id": "l_14_7", "codigo": "14.7", "tipo": "escolha_unica", "label": "Taxa extra \"Reserva\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"], "nota_revisao": "Revisão Cupola (Claude): a tabela de taxas acessórias da planilha foi transformada em uma pergunta por taxa."}, {"id": "l_14_8", "codigo": "14.8", "tipo": "escolha_unica", "label": "Taxa extra \"Análise de crédito\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"]}, {"id": "l_14_9", "codigo": "14.9", "tipo": "escolha_unica", "label": "Taxa extra \"Contrato digital\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"]}, {"id": "l_14_10", "codigo": "14.10", "tipo": "escolha_unica", "label": "Taxa extra \"Vistorias\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"]}, {"id": "l_14_11", "codigo": "14.11", "tipo": "escolha_unica", "label": "Taxa extra \"Limpeza\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"]}, {"id": "l_14_12", "codigo": "14.12", "tipo": "escolha_unica", "label": "Taxa extra \"TED proprietário\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"]}, {"id": "l_14_13", "codigo": "14.13", "tipo": "escolha_unica", "label": "Taxa extra \"Dimob\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"]}, {"id": "l_14_14", "codigo": "14.14", "tipo": "escolha_unica", "label": "Taxa extra \"Outras\": de quem é cobrada?", "obrigatorio": false, "opcoes": ["Inquilino", "Proprietário", "Ambos", "Não cobra"]}, {"id": "l_14_15", "codigo": "14.15", "tipo": "texto_longo", "label": "Como a imobiliária faz a gestão de IPTU?", "obrigatorio": false}, {"id": "l_14_16", "codigo": "14.16", "tipo": "texto_longo", "label": "Como a imobiliária faz a gestão financeira de condomínios e/ou outros encargos locatícios?", "obrigatorio": false}, {"id": "l_14_17", "codigo": "14.17", "tipo": "texto_longo", "label": "Como é feita a gestão dos locatários que precisam recolher IRRF? É direto no sistema? Esse monitoramento é feito mensalmente?", "obrigatorio": false}, {"id": "l_14_18", "codigo": "14.18", "tipo": "texto_longo", "label": "Como a imobiliária envia a Dimob?", "obrigatorio": false}, {"id": "l_14_19", "codigo": "14.19", "tipo": "texto_curto", "label": "Qual a rentabilidade média mensal da imobiliária, em termos percentuais? (resultado dividido pela receita)", "obrigatorio": false}, {"id": "l_14_20", "codigo": "14.20", "tipo": "texto_longo", "label": "Quais os três principais desafios que a imobiliária enfrenta relacionados ao setor financeiro?", "obrigatorio": false}]}, {"id": "gestao-administrativa", "titulo": "15. Gestão Administrativa", "perguntas": [{"id": "l_15_1", "codigo": "15.1", "tipo": "texto_longo", "label": "Há um gestor ou coordenador dedicado exclusivamente à área administrativa de locação? Se sim, qual o nome e cargo?", "obrigatorio": false}, {"id": "l_15_2", "codigo": "15.2", "tipo": "texto_longo", "label": "Qual o foco principal desse gestor: acompanhamento de indicadores, resolução de conflitos ou gestão direta da equipe?", "obrigatorio": false}, {"id": "l_15_3", "codigo": "15.3", "tipo": "texto_longo", "label": "Quais são as principais rotinas de controle administrativo? (ex.: conferência de repasses, auditoria de contratos, seguros)", "obrigatorio": false}, {"id": "l_15_4", "codigo": "15.4", "tipo": "texto_longo", "label": "Quais indicadores administrativos são acompanhados mensalmente pelo gestor? (ex.: taxa de renovação, índice de reajuste, vacância)", "obrigatorio": false}, {"id": "l_15_5", "codigo": "15.5", "tipo": "texto_longo", "label": "Como é feita a integração entre o administrativo e o comercial para evitar ruídos na entrada de novos contratos?", "obrigatorio": false}, {"id": "l_15_6", "codigo": "15.6", "tipo": "texto_longo", "label": "A equipe administrativa tem autonomia para negociar reajustes e renovações ou tudo passa pelo gestor?", "obrigatorio": false}, {"id": "l_15_7", "codigo": "15.7", "tipo": "texto_longo", "label": "Como o gestor acompanha os processos de manutenção e rescisão?", "obrigatorio": false}, {"id": "l_15_8", "codigo": "15.8", "tipo": "texto_longo", "label": "Como e com qual frequência o gestor comercial de locação dá feedbacks para a equipe comercial?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): duplicada pela 8.14 (e fala em gestor comercial dentro da aba administrativa)."}, {"id": "l_15_9", "codigo": "15.9", "tipo": "texto_longo", "label": "Como e com que frequência o gestor comercial de locação realiza 1:1 com os seus liderados?", "obrigatorio": false, "ativo": false, "nota_revisao": "Revisão Cupola (Claude): duplicada pela 8.15 (e fala em gestor comercial dentro da aba administrativa)."}, {"id": "l_15_10", "codigo": "15.10", "tipo": "texto_longo", "label": "Quais os três principais desafios da gestão administrativa hoje?", "obrigatorio": false}]}]}$tpl$::jsonb
